use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

/// How many times to offer the notification before giving up. The contract
/// requires `notified == true` on every output, so a run whose notification is
/// never accepted produces no output at all (it traps) rather than a report
/// that claims something false.
const NOTIFY_ATTEMPTS: u32 = 3;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Clock: read the wall-clock time once.
        let seconds = wall_clock::now().seconds;

        // HTTP: one fetch of the given feed. A transport failure is a value,
        // so a down feed counts as zero characters fetched rather than failing
        // the heartbeat. A host outside the allowlist traps at the boundary.
        let (fetched, status) = match http_client::fetch(&feed_url) {
            Ok(body) => {
                let count = body.chars().count();
                (u32::try_from(count).unwrap_or(u32::MAX), "ok")
            }
            Err(_) => (0u32, "fetch failed"),
        };

        // Notifier: report the heartbeat to the digest channel.
        let message = format!(
            "heartbeat at {seconds}: {status}, {fetched} characters from {feed_url}"
        );

        let mut notified = false;
        for _ in 0..NOTIFY_ATTEMPTS {
            if notifier::notify(&message) {
                notified = true;
                break;
            }
        }

        // ensures notified == true: never report a notification that was not
        // accepted. With panic = "abort" this is a trap, so no output is
        // produced if the channel refused every attempt.
        if !notified {
            panic!("heartbeat notification was not accepted by the notifier");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
